  FT["PH-H866"] = {"id":"PH-H866","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1031_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Three Hundred Thousand Pesos as Aid to the Philippine Tuberculosis Society","orig":"An Act Appropriating the Sum of Three Hundred Thousand Pesos as Aid to the Philippine Tuberculosis Society"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1031","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-12","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1031_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H866-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of three hundred thousand pesos is appropriated, out of any funds in the National Treasury not otherwise appropriated, as aid to the Philippine Tuberculosis Society with the condition that the said sum shall be used exclusively by the Quezon Institute for the following purposes:\n(1) For the improvement of its kitchen, including the purchase of equipment ₱100,000.00\n(2) For the construction of a laundry plant 120,000.00\n(3) For the construction of a garbage incinerator 80,000.00 Total ₱300,000.00"}},{"id":"PH-H866-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1954."}}],"pack":"ph-p12"};
